-- C13: every environment has the account type "user".
INSERT INTO "account_types" ("id", "environment_id", "name", "created_at", "updated_at")
SELECT openverify_new_id('acctp', e."created_at"), e."id", 'user', e."created_at", e."created_at"
  FROM "environments" e;--> statement-breakpoint
-- C13 resolution, applied to the past: inquiries that share a reference id in an environment
-- share one account with that reference id, as old as their oldest inquiry...
INSERT INTO "accounts" ("id", "environment_id", "account_type_id", "reference_id", "created_at", "updated_at")
SELECT openverify_new_id('acc', g."first_created_at"), g."environment_id", t."id", g."reference_id",
       g."first_created_at", g."first_created_at"
  FROM (SELECT "environment_id", "reference_id", min("created_at") AS "first_created_at"
          FROM "inquiries" WHERE "reference_id" IS NOT NULL
         GROUP BY "environment_id", "reference_id") g
  JOIN "account_types" t ON t."environment_id" = g."environment_id" AND t."name" = 'user';--> statement-breakpoint
UPDATE "inquiries" i SET "account_id" = a."id"
  FROM "accounts" a
 WHERE i."reference_id" IS NOT NULL AND a."environment_id" = i."environment_id"
   AND a."reference_id" = i."reference_id";--> statement-breakpoint
-- ...and an inquiry without a reference id gets an account of its own.
WITH "unreferenced" AS MATERIALIZED (
  SELECT i."id" AS "inquiry_id", i."environment_id", i."created_at",
         openverify_new_id('acc', i."created_at") AS "account_id"
    FROM "inquiries" i WHERE i."account_id" IS NULL
), "created" AS (
  INSERT INTO "accounts" ("id", "environment_id", "account_type_id", "created_at", "updated_at")
  SELECT u."account_id", u."environment_id", t."id", u."created_at", u."created_at"
    FROM "unreferenced" u
    JOIN "account_types" t ON t."environment_id" = u."environment_id" AND t."name" = 'user'
  RETURNING "id"
)
UPDATE "inquiries" i SET "account_id" = u."account_id"
  FROM "unreferenced" u WHERE i."id" = u."inquiry_id";--> statement-breakpoint
ALTER TABLE "inquiries" ALTER COLUMN "account_id" SET NOT NULL;--> statement-breakpoint
-- C10: Phase 1 inquiries expire one day after creation, the default lifetime.
UPDATE "inquiries" SET "expires_at" = "created_at" + interval '86400 seconds';--> statement-breakpoint
-- C11: the latest version of each template is its published version; older ones are
-- superseded. Phase 1 had no drafts, so each was published when it was created.
UPDATE "inquiry_template_versions" v
   SET "status" = (CASE WHEN v."version" = latest."version" THEN 'published' ELSE 'superseded' END)::"inquiry_template_version_status",
       "published_at" = v."created_at"
  FROM (SELECT "inquiry_template_id", max("version") AS "version"
          FROM "inquiry_template_versions" GROUP BY "inquiry_template_id") latest
 WHERE latest."inquiry_template_id" = v."inquiry_template_id";--> statement-breakpoint
-- C10: a revoked Phase 1 session was canceled; an unrevoked one past its TTL has expired.
UPDATE "inquiry_sessions" SET "status" = 'canceled', "canceled_at" = "revoked_at"
 WHERE "revoked_at" IS NOT NULL;--> statement-breakpoint
UPDATE "inquiry_sessions" SET "status" = 'expired', "expired_at" = "expires_at"
 WHERE "revoked_at" IS NULL AND "expires_at" <= now();--> statement-breakpoint
-- C15: sessions opened before MFA existed stay usable; no organization requires MFA yet.
UPDATE "user_sessions" SET "mfa_satisfied" = true;--> statement-breakpoint
-- C9: audit entries get their public ids, ordered like their creation times.
UPDATE "audit_logs" SET "public_id" = openverify_new_id('aud', "created_at");--> statement-breakpoint
ALTER TABLE "audit_logs" ALTER COLUMN "public_id" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "audit_logs" ALTER COLUMN "public_id" SET DEFAULT openverify_new_id('aud');--> statement-breakpoint
-- C15: the built-in roles of every existing organization, with the permissions C15 lists.
-- The API re-synchronises built-in roles from @openverify/core (syncBuiltinRoles). Every
-- Phase 1 operator could do everything, so each becomes an admin and keeps that access.
INSERT INTO "roles" ("id", "organization_id", "key", "name", "builtin", "permissions")
SELECT openverify_new_id('role'), o."id", r."key", r."name", true, r."permissions"
  FROM "organizations" o
 CROSS JOIN (VALUES
   ('admin', 'Admin', ARRAY['inquiries:read', 'inquiries:write', 'inquiries:redact', 'inquiry-templates:read', 'inquiry-templates:write', 'inquiry-templates:publish', 'inquiry-sessions:read', 'inquiry-sessions:write', 'verifications:read', 'webhooks:read', 'webhooks:write', 'events:read', 'accounts:read', 'accounts:write', 'accounts:redact', 'api-keys:read', 'api-keys:write', 'api-logs:read', 'audit-logs:read', 'pii:view', 'users:read', 'users:write', 'roles:read', 'roles:write', 'settings:read', 'settings:write', 'environments:production']::text[]),
   ('developer', 'Developer', ARRAY['inquiry-templates:read', 'inquiry-templates:write', 'inquiry-templates:publish', 'webhooks:read', 'webhooks:write', 'api-keys:read', 'api-keys:write', 'api-logs:read', 'events:read', 'inquiries:read', 'inquiries:write', 'verifications:read', 'inquiry-sessions:read', 'inquiry-sessions:write', 'accounts:read', 'environments:production']::text[]),
   ('reviewer', 'Reviewer', ARRAY['inquiries:read', 'inquiries:write', 'inquiries:redact', 'verifications:read', 'inquiry-sessions:read', 'accounts:read', 'accounts:write', 'accounts:redact', 'events:read', 'pii:view']::text[]),
   ('viewer', 'Viewer', ARRAY['inquiries:read', 'inquiry-templates:read', 'inquiry-sessions:read', 'verifications:read', 'webhooks:read', 'events:read', 'accounts:read', 'api-keys:read', 'users:read', 'roles:read', 'settings:read']::text[])
 ) AS r("key", "name", "permissions");--> statement-breakpoint
INSERT INTO "user_roles" ("organization_id", "user_id", "role_id")
SELECT u."organization_id", u."id", r."id"
  FROM "users" u JOIN "roles" r ON r."organization_id" = u."organization_id" AND r."key" = 'admin';--> statement-breakpoint
