-- Hand edit: updated_at triggers for the new tables. The function now leaves updated_at
-- alone inside a KEK rewrap (`SET LOCAL openverify.kek_rewrap = 'on'`), which rewrites
-- ciphertext only and must not restart retention clocks (C16).
CREATE OR REPLACE FUNCTION "openverify_set_updated_at"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."updated_at" IS NOT DISTINCT FROM OLD."updated_at"
     AND coalesce(current_setting('openverify.kek_rewrap', true), '') <> 'on' THEN
    NEW."updated_at" := now();
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
