-- Hand edit: audit logs stay append-only, except that a KEK rewrap may rewrite their two
-- encrypted columns and nothing else.
CREATE OR REPLACE FUNCTION "openverify_reject_audit_log_update"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF coalesce(current_setting('openverify.kek_rewrap', true), '') = 'on'
     AND (to_jsonb(NEW) - 'ip' - 'user_agent') = (to_jsonb(OLD) - 'ip' - 'user_agent') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'audit_logs is append-only';
END;
$$;--> statement-breakpoint
-- Hand edit: C13 seeds the account type "user" in every environment. A trigger does it, so
-- environments created by any code path (seeds, tests, the API) have it.
CREATE OR REPLACE FUNCTION "openverify_seed_environment"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO "account_types" ("id", "environment_id", "name")
  VALUES (openverify_new_id('acctp'), NEW."id", 'user');
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE TRIGGER "environments_seed_account_types" AFTER INSERT ON "environments" FOR EACH ROW EXECUTE FUNCTION "openverify_seed_environment"();
